def signature(fig):
    """Data geometry and view limits, excluding typography/legend cosmetics."""
    result = []
    for ax in fig.axes:
        chunks = []
        def add(a):
            a = np.ascontiguousarray(np.asarray(a, dtype=float))
            chunks.append((list(a.shape), hashlib.sha256(a.tobytes()).hexdigest()))
        for line in ax.lines:
            add(line.get_xydata())
        for collection in ax.collections:
            add(collection.get_offsets())
            for path in collection.get_paths():
                add(path.vertices)
                if path.codes is not None:
                    add(path.codes)
        for rectangle in ax.patches:
            add(rectangle.get_path().vertices)
            if hasattr(rectangle, 'get_xy') and hasattr(rectangle, 'get_width'):
                add([*rectangle.get_xy(), rectangle.get_width(), rectangle.get_height()])
        result.append(dict(xlim=list(ax.get_xlim()), ylim=list(ax.get_ylim()),
                           xscale=ax.get_xscale(), yscale=ax.get_yscale(), data=chunks))
    return result


